SELECT pg_advisory_xact_lock(hashtext('lan347-free-talk-practice-example-image-urls'));
LOCK TABLE writing_expression IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE lan347_image_updates (
    expression_id BIGINT NOT NULL,
    example_index INTEGER NOT NULL CHECK (example_index IN (3, 4)),
    expected_sentence_text TEXT NOT NULL,
    image_url TEXT NOT NULL,
    PRIMARY KEY (expression_id, example_index),
    UNIQUE (image_url)
) ON COMMIT DROP;

INSERT INTO lan347_image_updates (
