    (1180, 4, 'Good — repetition helps it sink in.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1180/practice-examples/b5001dc5-7fe8-4e8b-adc6-58b18f2868d1.webp'),
    (1181, 3, 'Sales dropped, but we''re bouncing back this month.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1181/practice-examples/c10ecc97-198f-47f3-b555-df048ed0efd6.webp'),
    (1181, 4, 'I give myself one evening to be sad, then make a new study plan to bounce back.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1181/practice-examples/d207d71a-5355-40bb-9086-878115b6b14e.webp'),
    (1182, 3, 'It''s hard to tell without checking the label.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1182/practice-examples/a76bb6c5-d87b-42f5-b4c2-1a8d3d43f1be.webp'),
    (1182, 4, 'I can''t tell from these clouds.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1182/practice-examples/593f57ee-7f5d-4bba-8b89-4e53a331fabc.webp'),
    (1183, 3, 'From what I can tell, they''re only renovating.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1183/practice-examples/a93f49e3-6e76-47ae-a31d-50fc3e7a5618.webp'),
    (1183, 4, 'From what I can tell, both sides left satisfied.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1183/practice-examples/cafa041c-be5a-4e07-9fec-4dc36bc7fc53.webp'),
    (1184, 3, 'From what I gather, it''ll reopen next month.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1184/practice-examples/93a5b77b-80f3-4f26-94f5-c7fe6221efa2.webp'),
    (1184, 4, 'From what I gather, both sides made small concessions.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1184/practice-examples/4d18171b-d406-4c6c-b212-58a09201a2ad.webp'),
    (1185, 3, 'From what I''ve heard, tickets are going quickly.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1185/practice-examples/4fb734c8-0f41-4417-9dd5-7f2c3c3ccd4d.webp'),
    (1185, 4, 'From what I''ve heard, it''s quiet and convenient.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1185/practice-examples/ce35e34b-c9a6-476c-b78a-26560ed1d365.webp'),
    (1186, 3, 'The way I see it, mature trees are worth preserving.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1186/practice-examples/b29920db-8d02-45f7-92db-cefd9a7b9183.webp'),
    (1186, 4, 'The way I see it, we have room to negotiate.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1186/practice-examples/dc6c6063-894e-4704-8d7e-0847d8394119.webp'),
    (1187, 3, 'Fresh bread and kind service make it a winner in my book.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1187/practice-examples/ec4e02f5-9a07-482a-858f-e11f70bcc63e.webp'),
    (1187, 4, 'The ending alone makes it special in my book.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1187/practice-examples/e6ba1e60-cc37-45a3-9645-37444e883224.webp'),
    (1188, 3, 'For starters, let''s bring plenty of water.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1188/practice-examples/61859156-c686-44ea-bd4c-da7a5c280475.webp'),
    (1188, 4, 'For starters, he has exactly the experience we need.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1188/practice-examples/a2fffdde-4e78-4bcd-b534-12001eb72038.webp'),
    (1189, 3, 'First things first, make sure it has cooled completely.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1189/practice-examples/e1fe4aa7-e0c9-47a3-9cdf-281717312490.webp'),
    (1189, 4, 'First things first, we should confirm the budget.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1189/practice-examples/27585cb9-db32-4a9a-97e1-b36e8f79c887.webp'),
    (1190, 3, 'By all means—she''d love it.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1190/practice-examples/7c75b8d2-55dd-4cd4-9b4b-a0331488bf12.webp'),
    (1190, 4, 'By all means, but please handle it carefully.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1190/practice-examples/0c49aa5b-a639-4601-ae09-9de02676316e.webp'),
    (1191, 3, 'Not at all. It was easier than I expected.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1191/practice-examples/5d83fa1f-5926-4004-8086-633d2b3a7bd0.webp'),
    (1191, 4, 'Not at all. The seat is free.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1191/practice-examples/de9b9ded-0efa-48ab-8138-a3f31647eb3a.webp'),
    (1192, 3, 'No problem. There were still plenty of seats.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1192/practice-examples/18512b36-49ce-42fd-95a2-748d315c1633.webp'),
    (1192, 4, 'No problem. I''ll update my calendar.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1192/practice-examples/da4c8721-ad9d-4bfb-9d7f-babb467c072f.webp'),
    (1193, 3, 'The friendly staff are no doubt part of the reason.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1193/practice-examples/35a338c3-d504-4350-8713-e29e3548adb9.webp'),
    (1193, 4, 'No doubt about it—he''s trained for months.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1193/practice-examples/adb18267-2614-4243-81cd-a11536aa74ff.webp'),
    (1194, 3, 'With these clouds, odds are we won''t see much.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1194/practice-examples/454eee4a-7e12-4b32-a2d0-5cbd9f4e1550.webp'),
    (1194, 4, 'At this hour, odds are everyone has gone home.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1194/practice-examples/4e136cc0-6b97-4f27-8987-2349f6c24e9d.webp'),
    (1195, 3, 'Chances are you''ll need to reset it.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1195/practice-examples/eec3c2ba-7827-45c8-ae06-cf8f7c2361d0.webp'),
    (1195, 4, 'Chances are it''s delayed because of the snow.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1195/practice-examples/68c479e9-7903-496d-b21d-12447201a57a.webp'),
    (1196, 3, 'That depends on how quickly you read.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1196/practice-examples/e4a0b666-02df-4472-a3de-a2c37f27fb1d.webp'),
    (1196, 4, 'That depends on how long you''ll use the service.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1196/practice-examples/27b8f36d-f9a9-43ab-a0ae-f37f1552926c.webp'),
    (1197, 3, 'As it happens, I studied Portuguese in college.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1197/practice-examples/e4806764-65e3-46e6-8105-04f95af903db.webp'),
    (1197, 4, 'As it happens, I prefer the green ones.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1197/practice-examples/2b0f16f1-240d-4548-9f8c-72b1b991cf9d.webp'),
    (1198, 3, 'As luck would have it, someone had returned a copy that morning.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1198/practice-examples/b20f2d74-b6e4-4b0c-a62d-c7c8d349b99c.webp'),
    (1198, 4, 'As luck would have it, the rain began right after we went inside.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1198/practice-examples/aa23d114-67ff-45ac-835c-d937013a88fb.webp'),
    (1199, 3, 'Partly, perhaps. At any rate, it was moving.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1199/practice-examples/ed307c63-bf18-48f0-a4a3-6b8778c3f0fd.webp'),
    (1199, 4, 'Maybe not, but at any rate, we can choose a date.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1199/practice-examples/719d44f3-5d2a-4527-aa51-a6979b29ebb0.webp'),
    (1200, 3, 'In any event, she has several good options.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1200/practice-examples/0aff5c8d-1b0f-4649-a063-877ed9aacffa.webp'),
    (1200, 4, 'In any event, the building will remain closed tonight.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1200/practice-examples/4cbb3b64-158a-49a0-bf35-6fb381d2c420.webp'),
    (1201, 3, 'In that case, I''ll order the sorbet for you.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1201/practice-examples/1e38dbc3-d3fc-46cd-b64b-403103f4b683.webp'),
    (1201, 4, 'In that case, buying a new one makes sense.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1201/practice-examples/b2de812d-3f40-43db-a65d-72fa9d483502.webp'),
    (1202, 3, 'In which case, we need a different dessert.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1202/practice-examples/e57eaaf6-c6c8-45b3-8e6e-ff6bc55f5c9f.webp'),
    (1202, 4, 'In which case, we''d better start today.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1202/practice-examples/63da8b53-9d22-41a8-b99c-7e4b090f3d46.webp'),
    (1203, 3, 'If so, let''s keep the picnic plan.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1203/practice-examples/1f473f31-3fd8-4a03-a586-c88412d6a914.webp'),
    (1203, 4, 'If so, we won''t need another ticket.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1203/practice-examples/be411e74-f893-4841-a0a3-30af57e3fa0d.webp'),
    (1204, 3, 'It seats twenty, if not more.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1204/practice-examples/77c108eb-5dc5-40a3-951a-113344fc282d.webp'),
    (1204, 4, 'If not, I can collect it tomorrow.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1204/practice-examples/03c1da29-0569-4679-a5d5-8ed890dce7ef.webp'),
    (1205, 3, 'Even so, the event is likely to sell out.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1205/practice-examples/450de28c-15a7-4da6-ae04-0c944aed5e66.webp'),
    (1205, 4, 'Even so, she handled the change calmly.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1205/practice-examples/5ca6434d-89b6-4b3a-89c5-90435738ad1b.webp'),
    (1206, 3, 'Driving gives us flexibility. Having said that, the train is less tiring.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1206/practice-examples/d09bcfe5-2629-4bb8-a066-579f90253989.webp'),
    (1206, 4, 'I learned a lot. Having said that, it could have been shorter.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1206/practice-examples/90c79815-0942-4fa2-bfaf-fafa57ffd139.webp'),
    (1207, 3, 'Be that as it may, we cannot ignore its security problems.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1207/practice-examples/d8656745-9818-48d4-b413-c4bb4158afef.webp'),
    (1207, 4, 'Be that as it may, we can prevent it from happening again.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1207/practice-examples/2c5b462e-9dd7-42d2-b517-f8bb1c803ef0.webp'),
    (1208, 3, 'One way or another, we''ll have the reports ready.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1208/practice-examples/05cead18-0cf2-411e-8a96-58efb4bd88eb.webp'),
    (1208, 4, 'Yes, and I''ll find it one way or another.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1208/practice-examples/be400eab-d924-41f6-95c9-7209d3f23e6e.webp'),
    (1209, 3, 'To cut a long story short, they agreed to share the space.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1209/practice-examples/4a184820-a96f-4d1d-ba63-cc340190b0f1.webp'),
    (1209, 4, 'To cut a long story short, the owner is selling this one.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1209/practice-examples/b1e8d589-7248-4c4f-90cc-916d761fb936.webp'),
    (1210, 3, 'Suffice it to say, we slept in our coats.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1210/practice-examples/8117b3a9-85c2-4c5e-8f61-2ab3950ac44b.webp'),
    (1210, 4, 'Suffice it to say, it took the entire afternoon.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1210/practice-examples/7dde445f-1db9-428d-a2b3-ba0d0a8c0970.webp'),
    (1211, 3, 'No. All I''m saying is, we need a realistic schedule.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1211/practice-examples/4a8e8200-ca89-49d4-9726-145e4f8c08d0.webp'),
    (1211, 4, 'Not at all. All I''m saying is, the commute is long.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1211/practice-examples/cbfe9639-f022-47c0-b4be-52c926cbf2bd.webp'),
    (1212, 3, 'What I''m getting at is, demand changes with the season.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1212/practice-examples/61149ada-f455-4203-b643-096c877680a0.webp'),
    (1212, 4, 'What I''m getting at is, the introduction needs a clearer focus.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1212/practice-examples/70b68d28-eb47-4ec7-8a59-f7b9d92c2850.webp'),
    (1213, 3, 'What it comes down to is the age of the machine.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1213/practice-examples/ce84be47-39dc-4871-81a7-ebfbe4fbf34b.webp'),
    (1213, 4, 'What it comes down to is speed versus flexibility.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1213/practice-examples/fb8ea63d-e89d-4235-9c26-eb03ec8d5dc0.webp'),
    (1214, 3, 'To my mind, it was the strongest part.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1214/practice-examples/a40d1d48-4da4-4de5-827c-704dca3035c0.webp'),
    (1214, 4, 'To my mind, clearer signs should be the priority.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1214/practice-examples/432bac48-a1e7-4428-8d9c-242e11df93e2.webp'),
    (1215, 3, 'Speaking for myself, I prefer meeting in person.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1215/practice-examples/5f0ad3e5-b450-48b7-b841-2c0ed9f92c47.webp'),
    (1215, 4, 'Speaking for myself, I''d open a window.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1215/practice-examples/b93dd4c0-b4f1-4338-a427-9c619fccc307.webp'),
    (1216, 3, 'From my perspective, it is much safer at night.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1216/practice-examples/36ad974a-fb94-4d49-b2d4-3cd7f4e371d6.webp'),
    (1216, 4, 'From my perspective, the examples make it very accessible.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1216/practice-examples/b77ea607-5dc4-42c8-9430-e5e298b4f819.webp'),
    (1217, 3, 'In all fairness, they lost two days to a power cut.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1217/practice-examples/ab929c51-3d18-4ceb-821c-6ab19a3ddd25.webp'),
    (1217, 4, 'In all fairness, it is nearly ten years old.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1217/practice-examples/05e5ca41-8a5d-4ded-84de-ea9a66e1b5f9.webp'),
    (1218, 3, 'Seven years and three months, to be precise.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1218/practice-examples/2eacef70-1d92-4bfc-89c8-eec1182effe2.webp'),
    (1218, 4, 'It came to 86 dollars, to be precise.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1218/practice-examples/9749c430-3eb9-456a-b674-3d26a1c87f6e.webp'),
    (1219, 3, 'Yes, and more to the point, her experience matches the role.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1219/practice-examples/5b244a58-5003-4a06-8b9f-7be1dc8cae37.webp'),
    (1219, 4, 'A little, but more to the point, it prevents mistakes.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1219/practice-examples/6977d281-fa23-4373-adcb-714ca2e1bda1.webp'),
    (1220, 3, 'It is not open on weekends at all, for that matter.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1220/practice-examples/ecb5a215-1127-4e79-9999-0c8259408235.webp'),
    (1220, 4, 'I haven''t read it—or the report, for that matter.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1220/practice-examples/8dff9ec2-2212-4ae7-9261-314d409e8a4a.webp'),
    (1221, 3, 'Yes. By the same token, the afternoon group should have equal access.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1221/practice-examples/4d661e40-fcbe-48b0-8f7b-c3fb83ab0cf5.webp'),
    (1221, 4, 'Certainly. By the same token, supervisors need it as well.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1221/practice-examples/fe30201b-faeb-4b05-b682-9cbf29fd2c6c.webp'),
    (1222, 3, 'When you put it that way, I''d be glad to volunteer.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1222/practice-examples/127676cc-3af6-4fec-960d-663c63b240ae.webp'),
    (1222, 4, 'When you put it that way, waking up early is worth it.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1222/practice-examples/30d2beeb-86b7-484a-a322-f4bf46651a4c.webp'),
    (1223, 3, 'Now you''re asking. Let''s plan a picnic.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1223/practice-examples/274dcd74-42f5-4101-8a06-b147d342d80d.webp'),
    (1223, 4, 'Now you''re asking. The coastal road is beautiful.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1223/practice-examples/e6fd0e29-42dc-4080-95ea-430a4eacf105.webp'),
    (1224, 3, 'No, that''s beside the point. We need to stop it now.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1224/practice-examples/e44a35db-8c3a-4287-86d3-a755d6d6f536.webp'),
    (1224, 4, 'That''s beside the point if it has no accessible entrance.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1224/practice-examples/18151e8f-8f25-4cc4-bed2-18403a8692e6.webp'),
    (1225, 3, 'That''s not the point. It was delivered to the wrong address.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1225/practice-examples/2507a763-29e4-4d79-9e47-614247eb3b29.webp'),
    (1225, 4, 'That''s not the point. We simply need a backup plan.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1225/practice-examples/9f413165-5d8f-41a8-a9f0-1634a4db1b9d.webp'),
    (1226, 3, 'You''ve got a point. I''ll adjust the budget.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1226/practice-examples/f6f76679-3410-4137-bd90-45742b98f584.webp'),
    (1226, 4, 'You''ve got a point. Noise matters more than speed here.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1226/practice-examples/1885d39c-dfb8-4742-a76f-5be6d4c698f5.webp'),
    (1227, 3, 'I see your point, so let''s move the launch back a week.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1227/practice-examples/fdb70a94-4595-4cbf-92f5-d3ce5d896cbc.webp'),
    (1227, 4, 'I see your point. That is worth considering.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1227/practice-examples/986e7daf-5e49-4344-a5e6-03f008b5010d.webp'),
    (1228, 3, 'I take your point, so let''s compare the full costs.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1228/practice-examples/b7156329-fc6b-408b-84e0-531cf3b0fe75.webp'),
    (1228, 4, 'I take your point, and we''ll communicate earlier next time.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1228/practice-examples/8fe49c00-b833-4185-857a-36533d5fd353.webp'),
    (1229, 3, 'I hear what you''re saying. You can use the back office.', 'https://d19azau1un4t7r.cloudfront.net/content/expressions/1229/practice-examples/ea25652c-d7d0-45c2-a41e-af80ac99f06b.webp'),
