DO $$
DECLARE
    update_count INTEGER;
    expression_count INTEGER;
    invalid_expression_count INTEGER;
    matched_count INTEGER;
BEGIN
    SELECT COUNT(*), COUNT(DISTINCT expression_id)
    INTO update_count, expression_count
    FROM lan347_image_updates;
    IF update_count <> 1914 OR expression_count <> 957 THEN
        RAISE EXCEPTION 'LAN-347 requires 1914 image updates for 957 expressions, got % for %',
            update_count, expression_count;
    END IF;

    SELECT COUNT(*) INTO invalid_expression_count
    FROM (
        SELECT expression_id
        FROM lan347_image_updates
        GROUP BY expression_id
        HAVING ARRAY_AGG(example_index ORDER BY example_index) <> ARRAY[3, 4]
    ) invalid_expression;
    IF invalid_expression_count <> 0 THEN
        RAISE EXCEPTION 'LAN-347 requires example indexes 3 and 4 for every expression';
    END IF;

    SELECT COUNT(*) INTO matched_count
    FROM lan347_image_updates source
    JOIN writing_expression target
      ON target.id = source.expression_id
     AND target.expression_source = 'FREE_TALK'
     AND target.scenario_id IS NULL
     AND target.status = 'ACTIVE'
     AND target.target_locale = 'EN'
     AND target.base_locale = 'KR'
     AND jsonb_array_length(target.practice_examples_payload) = 4
     AND target.practice_examples_payload -> (source.example_index - 1) ->> 'sentenceText'
         = source.expected_sentence_text;
    IF matched_count <> 1914 THEN
        RAISE EXCEPTION 'LAN-347 DB mapping mismatch: matched % of 1914 image updates', matched_count;
    END IF;
END $$;

CREATE TEMP TABLE lan347_original_payloads ON COMMIT DROP AS
SELECT target.id, target.practice_examples_payload
FROM writing_expression target
JOIN (SELECT DISTINCT expression_id FROM lan347_image_updates) source
  ON source.expression_id = target.id;

WITH update_urls AS (
    SELECT expression_id,
           MAX(image_url) FILTER (WHERE example_index = 3) AS example_3_url,
           MAX(image_url) FILTER (WHERE example_index = 4) AS example_4_url
    FROM lan347_image_updates
    GROUP BY expression_id
)
UPDATE writing_expression target
SET practice_examples_payload =
        jsonb_set(
            jsonb_set(
                target.practice_examples_payload,
                ARRAY['2', 'imageUrl'],
                to_jsonb(source.example_3_url),
                false
            ),
            ARRAY['3', 'imageUrl'],
            to_jsonb(source.example_4_url),
            false
        ),
    updated_at = CURRENT_TIMESTAMP
FROM update_urls source
WHERE target.id = source.expression_id
  AND (
      target.practice_examples_payload -> 2 ->> 'imageUrl' IS DISTINCT FROM source.example_3_url
      OR target.practice_examples_payload -> 3 ->> 'imageUrl' IS DISTINCT FROM source.example_4_url
  );

DO $$
DECLARE
    verified_count INTEGER;
    changed_non_target_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO verified_count
    FROM lan347_image_updates source
    JOIN writing_expression target ON target.id = source.expression_id
    WHERE target.practice_examples_payload -> (source.example_index - 1) ->> 'imageUrl'
        = source.image_url;
    IF verified_count <> 1914 THEN
        RAISE EXCEPTION 'LAN-347 post-update verification failed: verified % of 1914 URLs',
            verified_count;
    END IF;

    SELECT COUNT(*) INTO changed_non_target_count
    FROM writing_expression target
    JOIN lan347_original_payloads original ON original.id = target.id
    WHERE jsonb_array_length(target.practice_examples_payload)
              <> jsonb_array_length(original.practice_examples_payload)
       OR target.practice_examples_payload -> 0 <> original.practice_examples_payload -> 0
       OR target.practice_examples_payload -> 1 <> original.practice_examples_payload -> 1
       OR (target.practice_examples_payload -> 2) - 'imageUrl'
              <> (original.practice_examples_payload -> 2) - 'imageUrl'
       OR (target.practice_examples_payload -> 3) - 'imageUrl'
              <> (original.practice_examples_payload -> 3) - 'imageUrl';
    IF changed_non_target_count <> 0 THEN
        RAISE EXCEPTION 'LAN-347 changed practice payload fields outside example 3 and 4 imageUrl';
    END IF;
END $$;
